import type { DofusItem, DofusRecipe } from "../../types";



const COMPRESSED_SEED = "";

export type DofusSeedPayload = {
  items: DofusItem[];
  recipes: DofusRecipe[];
  exportedAt?: number;
};

let cachedData: DofusSeedPayload | null = null;

export async function getDofusDbSeedDataAsync(): Promise<DofusSeedPayload> {
  if (cachedData) return cachedData;

  // 1. Try standard DecompressionStream (Chrome 80+, Firefox 102+, Safari 16.4+, Node 18+)
  if (typeof DecompressionStream !== "undefined" && typeof Response !== "undefined" && typeof atob !== "undefined") {
    try {
      const binaryString = atob(COMPRESSED_SEED);
      const len = binaryString.length;
      const bytes = new Uint8Array(len);
      for (let i = 0; i < len; i++) {
        bytes[i] = binaryString.charCodeAt(i);
      }
      const ds = new DecompressionStream("gzip");
      const decompressedStream = new Response(bytes).body!.pipeThrough(ds);
      const text = await new Response(decompressedStream).text();
      cachedData = JSON.parse(text);
      return cachedData!;
    } catch (err) {
      console.warn("DecompressionStream seed decoding fallback:", err);
    }
  }

  if (typeof window === "undefined" && typeof process !== "undefined" && process.versions?.node) {
    try {
      const zlibMod = await import(/* @vite-ignore */ "zlib");
      const buffer = Buffer.from(COMPRESSED_SEED, "base64");
      const decompressed = zlibMod.gunzipSync(buffer).toString("utf-8");
      cachedData = JSON.parse(decompressed);
      return cachedData!;
    } catch (err) {
      console.error("Error in Node zlib decompression:", err);
    }
  }

  return cachedData || { items: [], recipes: [] };
}

export function getDofusDbSeedData(): DofusSeedPayload {
  if (cachedData) return cachedData;
  if (typeof process !== "undefined" && process.versions?.node) {
    try {
      // Synchronous Node execution for server/scripts
      // eslint-disable-next-line @typescript-eslint/no-require-imports
      const buffer = Buffer.from(COMPRESSED_SEED, "base64");
      // @ts-ignore
      const zlib = (globalThis as any).require ? (globalThis as any).require("zlib") : null;
      if (zlib) {
        const decompressed = zlib.gunzipSync(buffer).toString("utf-8");
        cachedData = JSON.parse(decompressed);
        return cachedData!;
      }
      return cachedData!;
    } catch (e) {
      console.error("Error in getDofusDbSeedData sync:", e);
    }
  }
  return cachedData || { items: [], recipes: [] };
}
